/** Motion: tween(Motion.STANDARD_MS, easing = Motion.Enter) to appear, tween(Motion.STANDARD_EXIT_MS, easing = Motion.Exit)
 *  to leave. The springs are MotionScheme.standard()'s: spatial (position, size) damping 0.9 / stiffness 700;
 *  effects (colour, opacity) damping 1 / stiffness 1600. Not the expressive scheme: it bounces.
 *  With Remove animations on, drop movement and scaling and keep at most a fade. */
object Motion {
    const val HOVER_IN_MS = 0
    const val HOVER_OUT_MS = 150
    const val FAST_MS = 100
    const val STANDARD_MS = 180
    const val SLOW_MS = 250
    const val ZOOM_MS = 300
    const val FAST_EXIT_MS = 67
    const val STANDARD_EXIT_MS = 120
    const val SLOW_EXIT_MS = 167
    const val ZOOM_EXIT_MS = 200
    val Enter = CubicBezierEasing(0.2f, 0f, 0f, 1f)
    val Exit = CubicBezierEasing(0.3f, 0f, 1f, 1f)
    fun <T> spatial(): SpringSpec<T> = spring(dampingRatio = 0.9f, stiffness = 700f)
    fun <T> effects(): SpringSpec<T> = spring(dampingRatio = 1f, stiffness = 1600f)
}

/** Gestures on photos and video. Pinch from fit (1) to ZOOM_MAX; a double tap toggles fit and ZOOM_DOUBLE_TAP at the
 *  tap point. Pans fling with the platform decay (rememberSplineBasedDecay(), as lists do) and spring back from the
 *  edges with Motion.spatial(). A swipe down closes the viewer past DISMISS_DISTANCE of the height or dismissVelocity
 *  per second, the background fading with the drag. The grid opens the viewer with a shared element
 *  (SharedTransitionLayout, Motion.ZOOM_MS). Sliders and dials snap to their detent within DETENT_ZONE of the range:
 *  snapped(value, range) plus Haptic.snap when the value lands on it. */
object MediaGesture {
    const val ZOOM_DOUBLE_TAP = 2.5f
    const val ZOOM_MAX = 8f
    const val DISMISS_DISTANCE = 0.25f
    val dismissVelocity = 800.dp
    const val DETENT_ZONE = 0.02f

    /** The value, pulled to [target] when it is within DETENT_ZONE of the range from it. */
    fun snapped(value: Float, range: ClosedFloatingPointRange<Float>, target: Float = 0f): Float =
        if (abs(value - target) <= (range.endInclusive - range.start) * DETENT_ZONE) target else value
}

/** Haptics, one per role: selection (a tool, a segment, a picture picked), snap (a slider or dial reaching its detent,
 *  a crop edge meeting a guide), success (an export or save finished), failure (it failed). Play them on the event,
 *  never on every frame: LocalHapticFeedback.current.performHapticFeedback(Haptic.snap). Needs Compose UI 1.8; the
 *  system maps each to HapticFeedbackConstants (selection SEGMENT_TICK, snap GESTURE_THRESHOLD_ACTIVATE, success CONFIRM, failure REJECT). */
object Haptic {
    val selection = HapticFeedbackType.SegmentTick
    val snap = HapticFeedbackType.GestureThresholdActivate
    val success = HapticFeedbackType.Confirm
    val failure = HapticFeedbackType.Reject
}

/** The viewer scrim: a fixed dark gradient from the top or bottom edge inward, under the viewer's white controls
 *  (AppTheme.colors.onMedia), in place of glass over the photo, which would shift its colours. Tapping the picture hides
 *  the controls and the scrim together. It holds 56 % black under the controls, so white text and icons pass
 *  4.5:1 even over a white photo, e.g. Box(Modifier.fillMaxWidth().height(ViewerScrim.height).background(ViewerScrim.top)) */
object ViewerScrim {
    val height = AppSize.viewerScrim
    val top = Brush.verticalGradient(
        0f to Color(0xA3000000),
        0.7f to Color(0x8F000000),
        1f to Color(0x00000000),
    )
    val bottom = Brush.verticalGradient(
        0f to Color(0x00000000),
        0.3f to Color(0x8F000000),
        1f to Color(0xA3000000),
    )
}

/** The transparency checkerboard behind a cut-out: Modifier.checkerboard(AppTheme.colors). */
fun Modifier.checkerboard(colors: ExtendedColors, square: Dp = AppSize.checker): Modifier = drawBehind {
    val s = square.toPx()
    drawRect(colors.checkerA)
    var row = 0
    while (row * s < size.height) {
        var column = if (row % 2 == 0) 1 else 0
        while (column * s < size.width) {
            drawRect(colors.checkerB, topLeft = Offset(column * s, row * s), size = Size(s, s))
            column += 2
        }
        row++
    }
}

/** A selected picture (thumbnail grid, generated results): an AppSize.selectOutline outline of mediaSelected inside its
 *  edge, drawn over the picture; add the AppSize.selectCheck check badge (primaryFill circle, white check, 1.5 dp
 *  white ring) at the bottom end. Never a tint over the picture: it changes how its colours read. */
fun Modifier.mediaSelected(selected: Boolean, colors: ExtendedColors): Modifier = drawWithContent {
    drawContent()
    if (selected) {
        val w = AppSize.selectOutline.toPx()
        drawRect(colors.mediaSelected, topLeft = Offset(w / 2, w / 2), size = Size(size.width - w, size.height - w), style = Stroke(w))
    }
}

/** The keyboard layer (shortcut hints in menus and tooltips, hover) is optional: show it only while a hardware keyboard
 *  is attached to a tablet or Chromebook (smallest width 600 dp and up), never on phones, as on iOS. Follows the
 *  keyboard as it comes and goes. */
@Composable
fun hasHardwareKeyboard(): Boolean {
    val config = LocalConfiguration.current
    return config.smallestScreenWidthDp >= 600 &&
        config.keyboard == Configuration.KEYBOARD_QWERTY && config.hardKeyboardHidden == Configuration.HARDKEYBOARDHIDDEN_NO
}

/** Material 3 picks corners by size key: text fields extraSmall, chips small, cards medium, sheets extraLarge. */
val AppShapes = Shapes(
    extraSmall = RoundedCornerShape(4.dp),
    small = RoundedCornerShape(6.dp),
    medium = RoundedCornerShape(8.dp),
    large = RoundedCornerShape(12.dp),
    extraLarge = RoundedCornerShape(16.dp)
)

/** Buttons are 12 dp (not Material's pill); tags and avatars are full pills. */
val ButtonShape = RoundedCornerShape(12.dp)
val TagShape = CircleShape

@Deprecated("Renamed to TagShape; kept for one version", ReplaceWith("TagShape"))
val ChipShape = TagShape

/** Roboto Flex (OFL): put the variable font in res/font as roboto_flex.ttf and pass
 *  AppTheme(fontFamily = robotoFlex(R.font.roboto_flex)); each weight sets the font's wght axis.
 *  Until then FontFamily.Default (the system Roboto) is used. */
fun robotoFlex(resId: Int): FontFamily = FontFamily(listOf(400, 500, 600, 700).map { Font(resId, FontWeight(it)) })

/** Material 3's own line height style: centred, not trimmed, so single-line text keeps its full line height. */
private val CentredLine = LineHeightStyle(LineHeightStyle.Alignment.Center, LineHeightStyle.Trim.None)

/** The Material 3 type scale in Roboto Flex. List row titles bodyLarge, metadata bodyMedium in text-2,
 *  labels and tags labelMedium; body text never below 12 sp. */
fun appTypography(family: FontFamily = FontFamily.Default) = Typography(
    displayLarge = TextStyle(fontFamily = family, fontSize = 57.sp, lineHeight = 64.sp, fontWeight = FontWeight.W400, letterSpacing = (-0.25).sp, lineHeightStyle = CentredLine),
    displayMedium = TextStyle(fontFamily = family, fontSize = 45.sp, lineHeight = 52.sp, fontWeight = FontWeight.W400, letterSpacing = 0.sp, lineHeightStyle = CentredLine),
    displaySmall = TextStyle(fontFamily = family, fontSize = 36.sp, lineHeight = 44.sp, fontWeight = FontWeight.W400, letterSpacing = 0.sp, lineHeightStyle = CentredLine),
    headlineLarge = TextStyle(fontFamily = family, fontSize = 32.sp, lineHeight = 40.sp, fontWeight = FontWeight.W400, letterSpacing = 0.sp, lineHeightStyle = CentredLine),
    headlineMedium = TextStyle(fontFamily = family, fontSize = 28.sp, lineHeight = 36.sp, fontWeight = FontWeight.W400, letterSpacing = 0.sp, lineHeightStyle = CentredLine),
    headlineSmall = TextStyle(fontFamily = family, fontSize = 24.sp, lineHeight = 32.sp, fontWeight = FontWeight.W400, letterSpacing = 0.sp, lineHeightStyle = CentredLine),
    titleLarge = TextStyle(fontFamily = family, fontSize = 22.sp, lineHeight = 28.sp, fontWeight = FontWeight.W400, letterSpacing = 0.sp, lineHeightStyle = CentredLine),
    titleMedium = TextStyle(fontFamily = family, fontSize = 16.sp, lineHeight = 24.sp, fontWeight = FontWeight.W500, letterSpacing = 0.15.sp, lineHeightStyle = CentredLine),
    titleSmall = TextStyle(fontFamily = family, fontSize = 14.sp, lineHeight = 20.sp, fontWeight = FontWeight.W500, letterSpacing = 0.1.sp, lineHeightStyle = CentredLine),
    bodyLarge = TextStyle(fontFamily = family, fontSize = 16.sp, lineHeight = 24.sp, fontWeight = FontWeight.W400, letterSpacing = 0.5.sp, lineHeightStyle = CentredLine),
    bodyMedium = TextStyle(fontFamily = family, fontSize = 14.sp, lineHeight = 20.sp, fontWeight = FontWeight.W400, letterSpacing = 0.25.sp, lineHeightStyle = CentredLine),
    bodySmall = TextStyle(fontFamily = family, fontSize = 12.sp, lineHeight = 16.sp, fontWeight = FontWeight.W400, letterSpacing = 0.4.sp, lineHeightStyle = CentredLine),
    labelLarge = TextStyle(fontFamily = family, fontSize = 14.sp, lineHeight = 20.sp, fontWeight = FontWeight.W500, letterSpacing = 0.1.sp, lineHeightStyle = CentredLine),
    labelMedium = TextStyle(fontFamily = family, fontSize = 12.sp, lineHeight = 16.sp, fontWeight = FontWeight.W500, letterSpacing = 0.5.sp, lineHeightStyle = CentredLine),
    labelSmall = TextStyle(fontFamily = family, fontSize = 11.sp, lineHeight = 16.sp, fontWeight = FontWeight.W500, letterSpacing = 0.5.sp, lineHeightStyle = CentredLine),
)

val AppTypography = appTypography()

/** Tabular digits, for amounts and counts: Text("−¥32.00", style = MaterialTheme.typography.bodyLarge.tabular) */
val TextStyle.tabular: TextStyle get() = copy(fontFeatureSettings = "tnum")

/** Timecodes and running times (timeline labels, player time, export time left), tabular so they never jitter:
 *  Text("0:12 / 1:04", style = MaterialTheme.typography.timecode) */
val Typography.timecode: TextStyle get() = labelLarge.tabular

/** The theme. dark and highContrast follow the system; the colour scheme is always this one (no dynamic colour).
 *  On Material 3 1.5.0-beta01 and later you may use, with the same arguments,
 *  MaterialExpressiveTheme(colorScheme = colors, motionScheme = MotionScheme.standard(), shapes = AppShapes,
 *  typography = typography, content = content), passing the colour scheme explicitly; never MotionScheme.expressive(). */
@Composable
fun AppTheme(
    dark: Boolean = isSystemInDarkTheme(),
    highContrast: Boolean = isSystemHighContrast(),
    fontFamily: FontFamily = FontFamily.Default,
    content: @Composable () -> Unit,
) {
    val colors = when {
        dark && highContrast -> DarkHighContrastColors
        dark -> DarkColors
        highContrast -> LightHighContrastColors
        else -> LightColors
    }
    val extended = when {
        dark && highContrast -> DarkHighContrastExtendedColors
        dark -> DarkExtendedColors
        highContrast -> LightHighContrastExtendedColors
        else -> LightExtendedColors
    }
    val typography = remember(fontFamily) { appTypography(fontFamily) }
    CompositionLocalProvider(LocalExtendedColors provides extended) {
        MaterialTheme(colorScheme = colors, shapes = AppShapes, typography = typography, content = content)
    }
}

/** Brand surfaces: the onboarding and paywall hero, empty-state art, the about tile, the launch screen and the
 *  export-complete page carry the app icon's material in light and dark mode alike: its graphite base lit from the top
 *  (brandSurfaceTop -> brandSurfaceBottom), its light body and its own accent (brandAccentLight -> brandAccent: brand
 *  art only, never a control). The working screens stay as they are. A tile has the iOS icon corner, 22.37 % of its side. */
object Brand {
    fun surface(colors: ExtendedColors) = Brush.verticalGradient(listOf(colors.brandSurfaceTop, colors.brandSurfaceBottom))
    fun body(colors: ExtendedColors) = Brush.verticalGradient(listOf(colors.brandBodyTop, colors.brandBodyBottom))
    fun accent(colors: ExtendedColors) = Brush.verticalGradient(listOf(colors.brandAccentLight, colors.brandAccent))
    /** the icon's corner, 22.37 % of the side at every size (CornerSize(Float) would be fixed pixels) */
    val TileShape = RoundedCornerShape(object : CornerSize {
        override fun toPx(shapeSize: Size, density: Density) = shapeSize.minDimension * 0.2237f
    })
    /** a square brand tile: the graphite with the icon's corner, and the brandEdge hairline (dark mode only) */
    fun tile(side: Dp, colors: ExtendedColors) = Modifier.size(side).clip(TileShape).background(surface(colors))
        .border(1.dp, colors.brandEdge, TileShape)
    /** the icon mark's height: hero art (onboarding, paywall, consent), empty states; below markMin show the app icon */
    val markHero = 120.dp
    val markEmpty = 88.dp
    val markMin = 64.dp
}

/** A brand panel: the icon's graphite, a dark island in a light page (text and controls inside take the dark scheme;
 *  onBrand is its text). Pass RectangleShape for a full-bleed header. */
@Composable
fun BrandPanel(
    modifier: Modifier = Modifier,
    shape: Shape = RoundedCornerShape(Radius.xl),
    content: @Composable ColumnScope.() -> Unit,
) {
    val hc = isSystemHighContrast()
    val edge = AppTheme.colors.brandEdge  // the page's, read before the dark scheme: a hairline in dark mode, clear in light
    CompositionLocalProvider(LocalExtendedColors provides if (hc) DarkHighContrastExtendedColors else DarkExtendedColors) {
        MaterialTheme(colorScheme = if (hc) DarkHighContrastColors else DarkColors, shapes = MaterialTheme.shapes,
                      typography = MaterialTheme.typography) {
            Column(modifier.clip(shape).background(Brand.surface(AppTheme.colors)).border(1.dp, edge, shape), content = content)
        }
    }
}

/** TopAppBar: opaque bg, and the same when content scrolls under it (no tonal lift); once scrolled, a 1 dp
 *  outlineVariant line under it, which you draw yourself, e.g. in a Column:
